<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Activity, Check, CircleAlert, Database, RefreshCw, Server, ShieldAlert } from 'lucide-vue-next'
import AdminLayout from '@/features/admin/components/AdminLayout.vue'
import AdminPanelState from '@/features/admin/components/AdminPanelState.vue'
import { useSession } from '@/app/stores/session'
import { useAdminSession } from '@/app/stores/admin-session'
import { fetchAdminRetention, fetchAdminSystemHealth, updateAdminRetention, type AdminHealthPayload, type AdminRetentionPayload } from '@/shared/api/admin'

const session = useSession(); const adminSession = useAdminSession(); const loading = ref(false); const error = ref<unknown>(null); const health = ref<AdminHealthPayload | null>(null); const retention = ref<AdminRetentionPayload | null>(null); const retentionLoading = ref(false); const retentionError = ref<unknown>(null); const retentionSaving = ref(false); const retentionNotice = ref('')
const auditDays = ref(0); const messageDays = ref(0); const toolResultDays = ref(0); const metricsDays = ref(0); const contentMode = ref('REDACTED')
const errorMessage = computed(() => error.value instanceof Error ? error.value.message : '系统健康读取失败')
const retentionErrorMessage = computed(() => retentionError.value instanceof Error ? retentionError.value.message : '数据保留策略读取失败')
const healthComponents = computed(() => health.value?.components ?? health.value?.services ?? [])
function statusTone(status?: string) { return /healthy|up|ok|正常/i.test(status ?? '') ? 'ok' : /down|failed|error|异常/i.test(status ?? '') ? 'bad' : 'warn' }
async function load() { if (!session.token.value) { error.value = new Error('管理员会话已失效'); return }; loading.value = true; error.value = null; try { health.value = await fetchAdminSystemHealth(session.token.value) } catch (cause) { error.value = cause } finally { loading.value = false } }
async function loadRetention() { if (!session.token.value || !adminSession.can('admin.system.read')) return; retentionLoading.value = true; retentionError.value = null; retentionNotice.value = ''; try { retention.value = await fetchAdminRetention(session.token.value); auditDays.value = retention.value.auditDays ?? 0; messageDays.value = retention.value.messageDays ?? 0; toolResultDays.value = retention.value.toolResultDays ?? 0; metricsDays.value = retention.value.metricsDays ?? 0; contentMode.value = retention.value.contentMode || 'REDACTED' } catch (cause) { retentionError.value = cause } finally { retentionLoading.value = false } }
async function saveRetention() { if (!session.token.value || !retention.value || !adminSession.can('admin.system.retention.manage')) return; const values = [auditDays.value, messageDays.value, toolResultDays.value, metricsDays.value]; if (values.some((value) => !Number.isInteger(value) || value < 1 || value > 3650)) { retentionError.value = new Error('保留天数必须是 1 到 3650 之间的整数'); return }; const reason = window.prompt('请输入保留策略变更原因')?.trim(); if (!reason || !window.confirm('确认提交数据保留策略变更？')) return; retentionSaving.value = true; retentionError.value = null; retentionNotice.value = ''; try { retention.value = await updateAdminRetention(session.token.value, { auditDays: auditDays.value, messageDays: messageDays.value, toolResultDays: toolResultDays.value, metricsDays: metricsDays.value, contentMode: contentMode.value, expectedVersion: retention.value.version ?? 0, idempotencyKey: crypto.randomUUID(), reason, confirmed: true }); auditDays.value = retention.value.auditDays ?? auditDays.value; messageDays.value = retention.value.messageDays ?? messageDays.value; toolResultDays.value = retention.value.toolResultDays ?? toolResultDays.value; metricsDays.value = retention.value.metricsDays ?? metricsDays.value; contentMode.value = retention.value.contentMode || contentMode.value; retentionNotice.value = '保留策略已更新' } catch (cause) { retentionError.value = cause } finally { retentionSaving.value = false } }
onMounted(async () => { await adminSession.ensure(session.token.value); await Promise.all([load(), loadRetention()]) })
</script>
<template>
  <AdminLayout active-id="system"><section class="admin-page-v2"><header class="admin-page-v2__header"><div><div class="admin-page-v2__crumb">Admin / <strong>System</strong></div><h1>系统状态</h1><p>查看管理员范围内的服务健康、版本和错误摘要。</p></div><div class="admin-page-v2__actions"><button class="admin-button-v2" type="button" :disabled="loading || retentionSaving" @click="load"><RefreshCw :class="{ 'is-spinning': loading }" aria-hidden="true" />刷新</button></div></header><div v-if="error" class="admin-error-v2" role="alert"><ShieldAlert aria-hidden="true" /><span>{{ errorMessage }}</span><button type="button" @click="load">重试</button></div><div class="admin-grid"><article class="admin-card-v2 admin-span-8"><div class="admin-card-v2__header"><div><h2>服务健康</h2><p>不使用本地默认状态覆盖服务端结果。</p></div><Server aria-hidden="true" /></div><AdminPanelState v-if="loading" state="loading" title="正在检查系统状态" /><AdminPanelState v-else-if="error" state="error" :message="errorMessage" @retry="load" /><AdminPanelState v-else-if="!health" state="empty" title="尚未返回健康状态" message="服务端没有返回健康检查数据。" /><div v-else class="admin-table-wrap"><table class="admin-table-v2"><thead><tr><th>服务</th><th>状态</th><th>版本</th><th>检查时间</th><th>队列/错误摘要</th></tr></thead><tbody><tr v-for="service in healthComponents" :key="service.serviceName"><td><strong>{{ service.serviceName || '未命名服务' }}</strong></td><td><span class="admin-status-v2" :class="`admin-status-v2--${statusTone(service.status)}`">{{ service.status || '未知' }}</span></td><td>{{ service.version || '-' }}</td><td>{{ service.checkedAt ? new Date(service.checkedAt).toLocaleString('zh-CN') : '-' }}</td><td>{{ service.errorSummary || '-' }}<small v-if="service.queueDepth != null">队列 {{ service.queueDepth }}</small></td></tr></tbody></table><div v-if="!healthComponents.length" class="admin-empty-v2"><Activity aria-hidden="true" /><div><strong>没有服务条目</strong><p>健康接口已返回，但没有可展示的服务记录。</p></div></div><div v-if="health.errors?.length" class="admin-system-errors"><strong>近期错误</strong><ul><li v-for="(item, index) in health.errors" :key="`${item.component || 'error'}-${index}`">{{ item.component || '系统' }} · {{ item.category || 'ERROR' }} · {{ item.summary || '未知错误' }}</li></ul></div></div></article><article class="admin-card-v2 admin-span-4 admin-card-v2--pad"><h2>平台状态</h2><p>总体状态：<span class="admin-status-v2" :class="`admin-status-v2--${statusTone(health?.status)}`">{{ health?.status || '未读取' }}</span></p><p>版本：{{ health?.version || '-' }}</p><p>生成时间：{{ health?.generatedAt || '-' }}</p><p><CircleAlert aria-hidden="true" /> 高风险策略变更会要求原因和二次确认。</p></article><article class="admin-card-v2 admin-span-12"><div class="admin-card-v2__header"><div><div><h2>数据保留策略</h2><p>读取审计、消息、工具结果和统计数据的服务端策略。</p></div></div><div class="admin-page-v2__actions"><button v-if="adminSession.can('admin.system.retention.manage')" class="admin-button-v2 admin-button-v2--dark" type="button" :disabled="retentionSaving || retentionLoading || !retention" @click="saveRetention"><Check aria-hidden="true" />保存策略</button><Database aria-hidden="true" /></div></div><AdminPanelState v-if="retentionLoading" state="loading" title="正在读取保留策略" /><AdminPanelState v-else-if="retentionError" state="error" :message="retentionErrorMessage" @retry="loadRetention" /><AdminPanelState v-else-if="!retention" state="empty" title="尚未返回保留策略" message="服务端没有提供当前策略，不使用本地默认天数。" /><div v-else class="admin-card-v2__body"><div class="admin-retention-grid"><label>审计记录<input v-if="adminSession.can('admin.system.retention.manage')" v-model.number="auditDays" type="number" min="1" max="3650" inputmode="numeric" /><span v-else>{{ retention.auditDays ?? '-' }} 天</span></label><label>消息<input v-if="adminSession.can('admin.system.retention.manage')" v-model.number="messageDays" type="number" min="1" max="3650" inputmode="numeric" /><span v-else>{{ retention.messageDays ?? '-' }} 天</span></label><label>工具结果<input v-if="adminSession.can('admin.system.retention.manage')" v-model.number="toolResultDays" type="number" min="1" max="3650" inputmode="numeric" /><span v-else>{{ retention.toolResultDays ?? '-' }} 天</span></label><label>统计指标<input v-if="adminSession.can('admin.system.retention.manage')" v-model.number="metricsDays" type="number" min="1" max="3650" inputmode="numeric" /><span v-else>{{ retention.metricsDays ?? '-' }} 天</span></label><label>内容策略<select v-if="adminSession.can('admin.system.retention.manage')" v-model="contentMode"><option value="REDACTED">REDACTED</option><option value="METADATA_ONLY">METADATA_ONLY</option></select><span v-else>{{ retention.contentMode || '-' }}</span></label><div><span class="admin-retention-label">版本</span><strong>{{ retention.version ?? '-' }}</strong></div><div><span class="admin-retention-label">生效时间</span><strong>{{ retention.effectiveAt || '-' }}</strong></div></div><p v-if="retentionNotice" class="admin-success-note" role="status"><Check aria-hidden="true" /> {{ retentionNotice }}</p><p>当前会话{{ adminSession.can('admin.system.retention.manage') ? '具备' : '不具备' }}保留策略变更权限；观察员只读，服务端仍会再次校验角色和版本。</p></div></article></div></section></AdminLayout>
</template>
<style scoped>
dl { display:grid; grid-template-columns:120px 1fr; gap:16px; margin:0; }
dt { color:#a0a0a0; font-size:11px; }
dd { margin:0; font-size:12px; }
p svg { width:14px; vertical-align:-3px; }
.admin-retention-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:14px 18px; }
.admin-retention-grid label, .admin-retention-grid > div { display:grid; gap:6px; color:#777; font-size:11px; }
.admin-retention-grid input, .admin-retention-grid select { width:100%; min-height:34px; border:1px solid #e8e8e5; border-radius:6px; background:#fff; color:#1d1d1f; padding:7px 9px; font-size:12px; }
.admin-retention-grid strong, .admin-retention-grid span:not(.admin-retention-label) { color:#1d1d1f; font-size:12px; }
.admin-retention-label { color:#777; font-size:11px; }
.admin-success-note { color:#327a4b !important; }
.admin-system-errors { margin-top:18px; border-top:1px solid #f0f0ed; padding-top:14px; color:#a1443e; font-size:11px; }
.admin-system-errors ul { display:grid; gap:6px; margin:8px 0 0; padding-left:18px; }
@media (max-width:900px) { .admin-retention-grid { grid-template-columns:repeat(2,minmax(0,1fr)); } }
</style>
